import { z } from 'zod';
import { APP_CONFIG } from '@/lib/config/app.config';

// Course Create Schema (course_id is auto-generated by DB)
export const courseCreateSchema = z.object({
  course_name: z.string().min(1, 'Course name is required'),
  slug: z.string().min(1, 'Slug is required'),
  banner_image: z.any().optional(),
  cover_image: z.any().optional(),
  description: z.string().optional(),
  course_category_id: z.string().optional(),
  course_type_id: z.string().optional(),
  economical_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`),
  standard_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`),
  premium_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`),
  duration_type: z.string().default('hours'),
  duration: z.number().min(1, 'Duration must be at least 1'),
  level: z.string().optional(),
  status_id: z.string().min(1, 'Status is required'),
  created_by: z.string().default('Admin'),
});

// Course Update Schema
export const courseUpdateSchema = z.object({
  course_id: z.string().optional(),
  course_name: z.string().min(1, 'Course name is required'),
  slug: z.string().min(1, 'Slug is required'),
  banner_image: z.any().optional(),
  cover_image: z.any().optional(),
  description: z.string().optional(),
  course_category_id: z.string().optional(),
  course_type_id: z.string().optional(),
  economical_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`)
    .optional(),
  standard_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`)
    .optional(),
  premium_price: z.number()
    .min(APP_CONFIG.defaults.course.minPrice, `Price must be at least ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.minPrice}`)
    .max(APP_CONFIG.defaults.course.maxPrice, `Price cannot exceed ${APP_CONFIG.currency.primary.symbol}${APP_CONFIG.defaults.course.maxPrice.toLocaleString('en-IN')}`)
    .optional(),
  duration_type: z.string().default('hours'),
  duration: z.number().min(0).optional(),
  level: z.string().optional(),
  status_id: z.string().min(1, 'Status is required'),
  updated_by: z.string().default('Admin'),
});

export type CourseCreateFormData = z.infer<typeof courseCreateSchema>;
export type CourseUpdateFormData = z.infer<typeof courseUpdateSchema>;

